#include <iostream>

int main() {
    int energia{1};
    if (energia < 0 || energia > 9) {
        std::cout << "Dato invalido";
    } else {
        int rondas{0};
        while (energia < 9) {
            int aporte{3};
            if (9 - energia < aporte) {
                aporte = 9 - energia;
            }
            energia += aporte;
            ++rondas;
            std::cout << "Ronda " << rondas << ": " << energia << "\n";
        }
        std::cout << "Estado=" << energia << ";Rondas=" << rondas;
    }
    return 0;
}

